  // Content and modal boundaries follow the existing Flutter pages.
  Object.assign(state,{nPlatform:'android',nChannel:'direct',nVoice:'auto',nLevels:['DEBUG','INFO','WARN','ERROR'],nLogPlatforms:['Flutter','Android'],nLogQuery:'',nLogCleared:false});
  rSpecs['category-tools']={title:'分类工具',host:'leaf',kind:'dialog'};
  rSpecs['update-check']={title:'检查更新',host:'about',kind:'dialog'};
  rSpecs['feature-guide']={title:'功能使用说明',host:'smart',kind:'dialog'};
  rSpecs['voice-trigger']={title:'语音触发方式',host:'smart',kind:'dialog'};
  rSpecs['log-detail']={title:'日志详情',host:'flow-logs',kind:'dialog'};
  fDefine('update-check','检查更新','帮助与信息','settings/about_page.dart',()=>`<div class="n-update">${icon('circle-check')}<h3>已是最新版本</h3><p class="bc-small">当前版本 ${appVersion}</p></div><p class="bc-small">此处为设计预览，未请求更新服务。</p>${fCTA('r-close','知道了')}`);
  fDefine('feature-guide','快捷记账使用说明','自动化与识别','settings/smart_billing_page.dart',()=>`<h3>${esc(state.nFeature||'图片记账')}</h3><p class="n-copy">${state.nFeature==='分享记账'?'在其他应用中分享支付截图，选择蜜蜂记账，识别后核对保存。':state.nFeature==='语音记账'?'长按底部记账按钮，选择语音记账，说出金额、分类和备注，核对后保存。':'长按底部记账按钮，选择图片或拍照，识别后核对账单再保存。'}</p>${fMessage('需要先配置 AI 服务及对应的图像 / 语音能力。')}${fCTA('r-close','知道了')}`);
  fDefine('voice-trigger','语音触发方式','自动化与识别','settings/smart_billing_page.dart',()=>`<div class="n-options">${[['auto','自动检测','停顿后自动结束，无需持续按住'],['hold','按住说话','按住录音，松开结束']].map(([v,t,d])=>btn('n-voice:'+v,`<span><b>${t}</b><small>${d}</small></span>${state.nVoice===v?icon('check'):''}`,t,'n-option')).join('')}</div>`);
  fDefine('transfer-icon','转账图标设置','分类标签与预算','category/category_manage_page.dart',()=>`${surface(`<div class="d-identity"><span class="bc-entry-icon">${icon('arrow-left-right')}</span><div><h3>转账</h3><small>转账记录的默认分类图标</small></div></div><div class="f-icon-grid">${['arrow-left-right','repeat-2','wallet','landmark','banknote'].map(i=>btn('f-icon:'+i,icon(i),'选择'+i+'图标','',`aria-pressed="${state.fIcon===i}"`)).join('')}</div>${btn('f-file','上传自定义图标','上传自定义图标','f-inline-button')}`)}${fCTA('f-save:转账图标','保存图标')}`);
  fDefine('attachment-library','附件预览','导入导出与维护','settings/attachment_preview_page.dart',()=>alLibrary());
  function dCategoryManager(){const t=document.createElement('template');t.innerHTML=fOriginalCategoryManager();for(const b of t.content.querySelectorAll('[data-action^="d-manage-toggle:"]')){const name=b.dataset.action.split(':')[1];b.querySelector('.bc-entry-icon').innerHTML=jCategoryVisual(name,pIcon(name));}for(const b of t.content.querySelectorAll('.d-manage-children [data-action^="d-manage-detail:"]')){const parts=b.dataset.action.split(':'),name=parts[2];b.innerHTML=`<span class="n-child-icon">${jCategoryVisual(name,pIcon(parts[1]))}</span><span>${esc(name)}</span>`;}const head=t.content.querySelector('.bc-subhead');head.lastElementChild.outerHTML=`<div class="bc-row">${btn('f-go:category-tools',icon('sliders-horizontal'),'分类工具','bc-icon')}${btn('leaf:新建分类',icon('plus'),'新建分类','bc-icon')}</div>`;return t.innerHTML+menuCard([['f-go:transfer-icon','arrow-left-right','转账图标设置','预览与编辑转账分类图标']])+fLink('category-tools','sliders-horizontal','分类工具','排序、导入、分享与默认分类');}
  function dataManagement(){return nPreviousDataManagement().replace(menuRow('leaf:导出附件','archive','导出附件','将所有附件打包为压缩文件'),menuRow('f-go:attachment-library','images','附件预览','查看所有账单附件')+menuRow('leaf:导出附件','archive','导出附件','将所有附件打包为压缩文件'));}
  function smart(){const android=state.nPlatform==='android',gp=state.nChannel==='googlePlay',guide=(key,i,title,desc)=>menuRow('n-guide:'+key,i,title,desc);return `${subhead('智能记账')}${surface(fSelect('nPlatform','平台预览',[['android','Android'],['ios','iOS']],'android')+fSelect('nChannel','渠道预览',[['direct','直接安装 / TestFlight'],['googlePlay','Google Play']],'direct'),'n-preview-context')}${menuCard([['f-go:ai-settings','sparkles','AI小助手','配置AI模型和识别策略']])}${sectionLabel('快捷记账使用引导')}${surface(guide('图片记账','images','图片记账','从相册选择支付截图进行识别')+guide('拍照记账','camera','拍照记账','拍摄票据或支付截图')+guide('语音记账','mic','语音记账','通过语音输入快速记账'),'bc-menu-card')}${sectionLabel('系统入口')}${surface((android?guide('分享记账','share-2','分享记账','Android · 从其他应用分享支付截图'):'')+(!(android&&gp)?menuRow('f-go:'+(android?'android-auto':'ios-auto'),'scan-line',android?'截图自动记账':'截屏自动记账','平台设置与使用说明'):'')+menuRow('f-go:shortcuts','command','快捷指令','快速打开语音、拍照等记账方式'),'bc-menu-card')}${sectionLabel('识别后的默认行为')}${surface(switchRow('autoTags','tags','自动关联标签','根据分类关联常用标签')+switchRow('autoAttachment','paperclip','自动添加附件','将识别图片附在账单中')+switchRow('original','image','附件保存原图','按原始质量保存附件'),'bc-menu-card')}${sectionLabel('语音记账设置')}${surface(menuRow('f-go:voice-trigger','mic','语音触发方式','',state.nVoice==='auto'?'自动检测':'按住说话')+(state.nVoice==='auto'?`<label class="v4-range-field"><span class="v4-range-label">停顿结束时长<output>1.5 秒</output></span><input class="v4-range" data-n-silence type="range" min="500" max="4000" step="100" value="1500" aria-label="停顿结束时长"><small class="bc-small">停顿后自动结束识别</small></label>`:''),'bc-menu-card')}`;}
  rSpecs['execution-depth']={title:'执行深度',host:'flow-assistant-settings',kind:'sheet'};
  fDefine('execution-depth','执行深度','AI 与助手','ai/agent_assistant_settings_page.dart',()=>`<div class="n-options">${[['2','快速 · 2轮'],['4','标准 · 4轮'],['6','深入 · 6轮'],['8','自定义 · 8轮']].map(([v,l])=>btn('n-depth:'+v,`<span><b>${l}</b><small>最多 ${v} 轮模型执行</small></span>${String(state.nDepth||4)===v?icon('check'):''}`,l,'n-option')).join('')}</div>`);
  fDefs['assistant-settings'].body=()=>`${menuCard([['f-go:permissions','key-round','工具权限','逐项设置读取与写入工具权限']])}${menuCard([['f-go:memory','brain','助手记忆','管理当前账本的偏好与记忆']])}${menuCard([['f-go:activity','activity','助手活动','查看工具调用与执行记录']])}${menuCard([['f-go:execution-depth','sliders-horizontal','执行深度','最多 '+(state.nDepth||4)+' 轮模型执行']])}`;
  const nLogs=[{id:1,level:'DEBUG',platform:'Flutter',tag:'Database',message:'本地数据库已就绪',time:'09:41:01'},{id:2,level:'INFO',platform:'Flutter',tag:'App',message:'应用启动完成',time:'09:41:02'},{id:3,level:'WARN',platform:'Android',tag:'Permission',message:'演示：媒体权限尚未开启',time:'09:41:03'},{id:4,level:'ERROR',platform:'Flutter',tag:'Sync',message:'演示：连接暂时不可用',time:'09:42:10',error:'SyntheticConnectionError',stack:'SyncClient.connect → retry'}];
  function nLogsView(){const q=state.nLogQuery.toLowerCase(),rows=state.nLogCleared?[]:nLogs.filter(l=>state.nLevels.includes(l.level)&&state.nLogPlatforms.includes(l.platform)&&[l.tag,l.message,l.error||''].join(' ').toLowerCase().includes(q));return `<label class="p-search-box">${icon('search')}<input data-n-log-query placeholder="搜索内容、标签或错误" aria-label="搜索日志" value="${esc(state.nLogQuery)}"></label>${surface(`<label class="bc-small">日志级别</label><div class="v4-wrap n-filter">${['DEBUG','INFO','WARN','ERROR'].map(l=>btn('n-level:'+l,l,l,'v4-chip',`data-selected="${state.nLevels.includes(l)}" aria-pressed="${state.nLevels.includes(l)}"`)).join('')}</div><label class="bc-small">来源平台</label><div class="v4-wrap n-filter">${['Flutter',state.nPlatform==='ios'?'iOS':'Android'].map(l=>btn('n-log-platform:'+l,l,l,'v4-chip',`data-selected="${state.nLogPlatforms.includes(l)}" aria-pressed="${state.nLogPlatforms.includes(l)}"`)).join('')}</div>`)}<p class="bc-small n-log-count">总计 ${state.nLogCleared?0:nLogs.length} · 筛选后 ${rows.length}</p>${surface(rows.map(l=>btn('n-log-detail:'+l.id,`<span class="n-log-meta"><b data-level="${l.level}">${l.level}</b><small>${l.platform} · ${l.time}</small></span><span class="n-log-msg">[${l.tag}] ${l.message}</span>`,l.tag+' 日志详情','n-log-row')).join('')||'<p class="p-empty">没有匹配日志</p>')}${fCTA('f-download:logs','导出诊断日志')}${fCTA('n-clear-logs','清空日志')}`;}
  fDefs.logs.body=nLogsView;
  fDefine('log-detail','日志详情','帮助与信息','settings/log_center_page.dart',()=>{const l=nLogs.find(x=>x.id===state.nLogId)||nLogs[0];return `<div class="n-log-detail"><b>[${esc(l.tag)}]</b><p class="bc-small">${l.time} · ${l.level} · ${l.platform}</p><p>${esc(l.message)}</p>${l.error?`<pre>Error: ${esc(l.error)}</pre><pre>Stack Trace:\n${esc(l.stack)}</pre>`:''}</div>${fCTA('f-copy:合成日志详情','复制日志内容')}`;});
  fDefs['ai-settings'].body=()=>`${surface(fToggle('aiEnabled','启用 AI 识别','使用配置的模型服务',true))}${menuCard([['f-go:providers','server','AI 服务商管理','配置 API、模型与连接']])}${sectionLabel('能力分配')}${menuCard([['f-go:capabilities','message-square','文本对话','选择已配置服务商'],['f-go:capabilities','images','图像理解','用于图片与拍照记账'],['f-go:capabilities','mic','语音转文字','用于语音记账']])}${surface(`<details class="v4-accordion"><summary><span>高级设置<small>识别策略与自定义提示词</small></span>${icon('chevron-down')}</summary><div class="n-advanced">${fSelect('aiStrategy','识别策略',[['云端优先','云端优先'],['仅云端','仅云端']],'云端优先')}<p class="bc-small">本地优先 / 仅本地暂不可用</p>${fLink('prompt','notebook-pen','自定义提示词','查看与编辑识别提示词')}</div></details>`)}${fLink('assistant-settings','sparkles','助手设置','权限、记忆与执行设置')}`;
  root.addEventListener('input',e=>{if(e.target.matches('[data-n-log-query]')){const pos=e.target.selectionStart;state.nLogQuery=e.target.value;render();const x=phone.querySelector('[data-n-log-query]');x.focus({preventScroll:true});x.setSelectionRange(pos,pos);}if(e.target.matches('[data-n-silence]'))e.target.closest('label').querySelector('output').textContent=(Number(e.target.value)/1000).toFixed(1)+' 秒';});
  root.addEventListener('change',e=>{if(e.target.dataset.fField==='nPlatform'||e.target.dataset.fField==='nChannel'){state[e.target.dataset.fField]=e.target.value;state.nLogPlatforms=['Flutter',state.nPlatform==='ios'?'iOS':'Android'];render();}},true);
  root.addEventListener('click',e=>{const el=e.target.closest('[data-action]');if(!el)return;const [a,...parts]=el.dataset.action.split(':'),v=parts.join(':');if(a==='leaf'&&v==='检查更新'){e.preventDefault();e.stopImmediatePropagation();rOpenModal('update-check');return;}if(!a.startsWith('n-'))return;e.preventDefault();e.stopImmediatePropagation();if(a==='n-depth'){state.nDepth=Number(v);rDismiss();render();}else if(a==='n-guide'){state.nFeature=v;rOpenModal('feature-guide');}else if(a==='n-voice'){state.nVoice=v;rDismiss();render();}else if(a==='n-attachment'){state.detailId=1;state.uAttachmentCount=3;state.uAttachmentIndex=Number(v);rOpenModal('attachment-viewer');}else if(a==='n-level'||a==='n-log-platform'){const key=a==='n-level'?'nLevels':'nLogPlatforms',list=state[key];state[key]=list.includes(v)?list.filter(x=>x!==v):[...list,v];render();}else if(a==='n-log-detail'){state.nLogId=Number(v);rOpenModal('log-detail');}else if(a==='n-clear-logs')sheet('清空日志？',`<p class="bc-small">清空后无法恢复，导出的文件不受影响。</p>${fCTA('n-confirm-clear','确认清空','取消')}`);else if(a==='n-confirm-clear'){state.nLogCleared=true;closeSheet();render();}},true);
